#include "kernels/thermal_solver.hpp"
#include <iostream>
#include <iomanip>
#include <cassert>
using namespace unicore::thermal;
Model model(){Model m;m.nodes={{{0,0,0}},{{1,0,0}},{{0,1,0}},{{0,0,1}}};m.elements.push_back({{0,1,2,3},1e6,0,1000});m.fixed.assign(4,false);m.temperature.assign(4,0);for(auto ids:std::vector<std::array<int,3>>{{0,2,1},{0,1,3},{1,2,3},{2,0,3}}){Surface f;f.nodes=ids;f.emissivity=.8;f.surroundings=300;m.surfaces.push_back(f);}return m;}
int main(int argc,char**argv){if(argc>1)unicore::math::solver_options.preconditioner=argv[1];std::cout<<std::setprecision(16);std::atomic<bool>cancel{false};double sigma=stefan_boltzmann;
 {auto m=model();m.fixed.assign(4,true);m.temperature.assign(4,600);auto r=solve(m,cancel);double analytical=.8*sigma*(std::pow(600.,4)-std::pow(300.,4));for(auto f:r.radiation_flux)assert(std::abs(f-analytical)<1e-8);std::cout<<"A flux="<<r.radiation_flux[0]<<" expected="<<analytical<<" balance="<<r.energy_balance<<"\n";}
 for(double initial:{200.,1000.}){auto m=model();double load=.8*sigma*(std::pow(600.,4)-std::pow(300.,4))+10*300;for(auto &f:m.surfaces){f.flux=load;f.h=10;f.ambient=300;}auto r=solve(m,cancel,0,0,initial);for(double t:r.temperature)assert(std::abs(t-600)<1e-5);assert(std::abs(r.energy_balance)/r.heat_input<1e-8);std::cout<<"B/C initial="<<initial<<" T="<<r.temperature[0]<<" Newton="<<r.nonlinear_iterations<<" residual="<<r.residual<<" balance="<<r.energy_balance<<" relative_balance="<<std::abs(r.energy_balance)/r.heat_input<<"\n";}
 for(double dt:{.002,.001}){auto m=model();double area=(3+std::sqrt(3.))/2,volume=1./6;int steps=int(.2/dt);auto r=solve(m,cancel,dt,steps,600);auto derivative=[&](double t){return -area/(1000*volume)*.8*sigma*(std::pow(t,4)-std::pow(300.,4));};double reference=600,h=dt*steps/200000;for(int i=0;i<200000;++i){double a=derivative(reference),b=derivative(reference+h*a/2),c=derivative(reference+h*b/2),d=derivative(reference+h*c);reference+=h*(a+2*b+2*c+d)/6;}double mean=0;for(double t:r.temperature)mean+=t/4;assert(std::abs(mean-reference)<.05);assert(std::abs(r.energy_balance)<.01);std::cout<<"D dt="<<dt<<" Bi="<<4*.8*sigma*std::pow(600.,3)*(volume/area)/1e6<<" cooling="<<mean<<" RK4="<<reference<<" error="<<std::abs(mean-reference)<<" E balance="<<r.energy_balance<<" Newton="<<r.nonlinear_iterations<<"\n";}
 {auto m=model();std::vector<double> t{300,400,500,600},r(4,0);unicore::math::Sparse j(4);radiation(m,t,r,&j);for(int column=0;column<4;++column){auto plus=t,minus=t;plus[column]+=.001;minus[column]-=.001;std::vector<double>a(4,0),b(4,0);radiation(m,plus,a);radiation(m,minus,b);for(int row=0;row<4;++row)assert(std::abs((a[row]-b[row])/.002-j[row][column])<1e-6);}std::cout<<"Consistent surface tangent finite-difference PASS\n";}
 std::cout<<"Radiation native analytical checks PASS\n";
}
